import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { Line, Bar, Pie } from 'react-chartjs-2';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, 
  BarElement, ArcElement, Title, Tooltip, Legend, Filler
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, ArcElement, Title, Tooltip, Legend, Filler);

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isSignup, setIsSignup] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);
  const [authData, setAuthData] = useState({ username: '', password: '' });

  // 💰 VIRTUAL WALLET, HOLDINGS & LIVE PRICE STATES
  const [wallet, setWallet] = useState(100000); 
  const [holdings, setHoldings] = useState({}); 
  const [livePrice, setLivePrice] = useState(0); 
  const [priceHistory, setPriceHistory] = useState([]); 
  const prevDecisionRef = useRef(null); // Upgrade 3: AI Signal tracking

  const stockList = [
    { name: "HDFC Bank (₹816 Proof)", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "ICICI Bank", symbol: "ICICIBANK.NS" },
    { name: "Reliance Industries", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "Infosys", symbol: "INFY.NS" },
    { name: "Adani Enterprises", symbol: "ADANIENT.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  // 🟢 LIVE SIMULATION + AUTO-SELL LOGIC (Upgrade 1 & 2: Stop Loss & Take Profit)
  useEffect(() => {
    if (isLoggedIn && data) {
      setLivePrice(data.current_price);
      setPriceHistory([data.current_price]);

      const interval = setInterval(() => {
        setLivePrice(prev => {
          const fluctuation = (Math.random() - 0.5) * 2.5; 
          const newPrice = prev + fluctuation;
          
          // 🚀 AUTO-SELL LOGIC (Parallel Monitoring for all holdings)
          Object.keys(holdings).forEach(symbol => {
            if (holdings[symbol].qty > 0) {
              const buyPrice = holdings[symbol].avgPrice;
              const targetPrice = buyPrice * 1.005; // 0.5% Profit Target
              const stopLossPrice = buyPrice * 0.995; // 0.5% Stop Loss

              if (newPrice >= targetPrice) {
                executeAutoExecution(symbol, newPrice, "🚀 TARGET REACHED! Profit Captured.");
              } else if (newPrice <= stopLossPrice) {
                executeAutoExecution(symbol, newPrice, "🛡️ STOP LOSS TRIGGERED! Capital Saved.");
              }
            }
          });

          setPriceHistory(history => [...history, newPrice].slice(-20));
          return newPrice;
        });
      }, 1000);

      return () => clearInterval(interval);
    }
  }, [data, isLoggedIn, holdings]);

  // 🤖 AI SIGNAL ALERT (Upgrade 3)
  useEffect(() => {
    if (data && data.decision === "BUY" && prevDecisionRef.current !== "BUY") {
      alert(`🔔 AI SIGNAL ALERT: High probability BUY signal detected for ${data.symbol}!`);
    }
    prevDecisionRef.current = data?.decision;
  }, [data]);

  const executeAutoExecution = (symbol, price, reason) => {
    const qty = holdings[symbol].qty;
    setWallet(w => w + (price * qty));
    setHoldings(h => {
      const updated = { ...h };
      delete updated[symbol]; // Reset holdings after auto-sell
      return updated;
    });
    alert(`🤖 AUTO-EXECUTION: ${reason}\nSold at: ₹${price.toFixed(2)}`);
  };

  // 🟢 PROFIT/LOSS CALCULATION
  const calculatePnL = () => {
    let totalPnL = 0;
    Object.keys(holdings).forEach(symbol => {
      if (data && data.symbol === symbol) {
        totalPnL += (livePrice - holdings[symbol].avgPrice) * holdings[symbol].qty;
      }
    });
    return totalPnL;
  };

  const executeTrade = (action) => {
    if (!data) return;
    const price = livePrice;
    const symbol = data.symbol;

    if (action === "BUY") {
      if (wallet >= price) {
        setWallet(prev => prev - price);
        setHoldings(prev => {
          const current = prev[symbol] || { qty: 0, avgPrice: 0 };
          const newQty = current.qty + 1;
          const newAvg = ((current.avgPrice * current.qty) + price) / newQty;
          return { ...prev, [symbol]: { qty: newQty, avgPrice: newAvg } };
        });
        alert(`AI Trade Success: Bought 1 share of ${symbol}`);
      } else {
        alert("Insufficient balance!");
      }
    } else if (action === "SELL") {
      if (holdings[symbol] && holdings[symbol].qty > 0) {
        setWallet(prev => prev + (price * holdings[symbol].qty));
        setHoldings(prev => {
          const updated = { ...prev };
          delete updated[symbol];
          return updated;
        });
        alert(`AI Trade Success: Sold holdings of ${symbol}`);
      } else {
        alert("No shares to sell!");
      }
    }
  };

  const handleAuth = async () => {
    if(authData.username && authData.password) {
      setIsLoggedIn(true);
    } else {
      alert("Please enter credentials");
    }
  };

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        const result = Array.isArray(res.data) ? res.data[0] : res.data;
        setData(result);
        setLoading(false);
      })
      .catch(err => { console.error(err); setLoading(false); });
  };

  useEffect(() => {
    if (isLoggedIn) fetchData(selectedStock);
  }, [selectedStock, isLoggedIn]);

  const liveGraphData = {
    labels: priceHistory.map((_, i) => `${i}s`),
    datasets: [{
      label: `Live ${data?.symbol} Trend (₹)`,
      data: priceHistory,
      borderColor: '#4facfe',
      backgroundColor: 'rgba(79, 172, 254, 0.1)',
      fill: true,
      tension: 0.4,
      pointRadius: 0
    }]
  };

  const pieData = {
    labels: ['Equities', 'Hedge', 'Cash'],
    datasets: [{
      data: data?.regime === "STRESS" ? [40, 50, 10] : [70, 10, 20],
      backgroundColor: ['#4facfe', '#f85149', '#cbd5e1'],
      borderWidth: 0
    }]
  };

  const downloadReport = () => {
    const input = document.getElementById('report-area');
    html2canvas(input).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      pdf.addImage(imgData, 'PNG', 0, 0, 210, (canvas.height * 210) / canvas.width);
      pdf.save(`QuantShield_Report_${selectedStock}.pdf`);
    });
  };

  if (!isLoggedIn) {
    return (
      <div style={{ backgroundImage: `linear-gradient(rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.7)), url('https://i.ibb.co/XfXkY8C/rm373batch4-07.jpg')`, backgroundSize: 'cover', backgroundPosition: 'center', height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', fontFamily: "'Poppins', sans-serif" }}>
        <div style={{ background: 'rgba(255, 255, 255, 0.1)', backdropFilter: 'blur(15px)', padding: '50px', borderRadius: '30px', width: '900px', display: 'flex', gap: '40px', color: 'white', border: '1px solid rgba(255,255,255,0.2)' }}>
          <div style={{ flex: 1 }}>
             <h1 style={{ fontSize: '48px', fontWeight: '900', color: '#00f2fe' }}>QuantShield</h1>
             <p style={{ fontSize: '18px', opacity: 0.8 }}>Advanced AI-Driven Portfolio Optimization and Risk Forecasting System</p>
          </div>
          <div style={{ flex: 0.8, background: 'rgba(0, 0, 0, 0.4)', padding: '40px', borderRadius: '25px' }}>
            <h2 style={{ marginBottom: '20px' }}>LOGIN</h2>
            <input type="text" placeholder="USERNAME" onChange={(e) => setAuthData({...authData, username: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <input type="password" placeholder="PASSWORD" onChange={(e) => setAuthData({...authData, password: e.target.value})} style={{ width: '100%', padding: '12px', margin: '10px 0', background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.3)', color: 'white', borderRadius: '10px' }} />
            <button onClick={handleAuth} style={{ width: '100%', padding: '15px', background: 'linear-gradient(90deg, #00f2fe, #4facfe)', color: '#002f35', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>SIGN IN</button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      <div style={{ width: '260px', background: 'white', padding: '30px 20px', borderRight: '1px solid #e2e8f0', position: 'fixed', height: '100vh' }}>
        <h2 style={{ color: '#4facfe', fontWeight: '800', marginBottom: '40px', fontSize: '24px' }}>🛡️ QuantShield</h2>
        {["Dashboard", "Analytics", "Stocks", "Settings"].map(tab => (
          <div key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab === tab ? '#eff6ff' : 'transparent', color: activeTab === tab ? '#3b82f6' : '#64748b', padding: '15px', borderRadius: '12px', fontWeight: 'bold', marginBottom: '10px', cursor: 'pointer', transition: '0.3s' }}>
             {tab === "Dashboard" ? "📊 " : tab === "Analytics" ? "📈 " : tab === "Stocks" ? "💹 " : "⚙️ "}{tab}
          </div>
        ))}
        <div style={{ position: 'absolute', bottom: '30px', left: '20px', color: '#f85149', fontWeight: 'bold', cursor: 'pointer' }} onClick={() => setIsLoggedIn(false)}>Logout</div>
      </div>

      <div style={{ flex: 1, padding: '40px', marginLeft: '260px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <div>
            <h1 style={{ fontSize: '28px', fontWeight: '800', margin: 0 }}>{activeTab}</h1>
            <p style={{ color: '#64748b', fontSize: '14px' }}>QuantShield Algo-Terminal Active (1s Sync)</p>
          </div>
          <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <div style={{ background: 'white', padding: '12px 25px', borderRadius: '15px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px rgba(0,0,0,0.02)' }}>
              <span style={{ fontSize: '12px', color: '#64748b', fontWeight: 'bold' }}>WALLET: </span>
              <b style={{ color: '#22c55e', fontSize: '18px' }}>₹{wallet.toLocaleString()}</b>
            </div>
            {activeTab === "Dashboard" && data && <button onClick={downloadReport} style={{ padding: '12px 25px', background: '#1e293b', color: 'white', borderRadius: '12px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}>📥 Report</button>}
          </div>
        </div>

        <div id="report-area">
          {activeTab === "Dashboard" && data && (
            <>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' }}>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0' }}>
                  <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold' }}>TOTAL P&L</div>
                  <div style={{ fontSize: '24px', fontWeight: '900', color: calculatePnL() >= 0 ? '#166534' : '#991b1b' }}>₹{calculatePnL().toFixed(2)}</div>
                </div>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0' }}>
                  <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold' }}>LIVE TICKER PRICE</div>
                  <div style={{ fontSize: '24px', fontWeight: '900', color: '#3b82f6' }}>₹{livePrice.toFixed(2)}</div>
                </div>
                <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0' }}>
                  <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold' }}>AI VERDICT</div>
                  <div style={{ fontSize: '24px', fontWeight: '900', color: data.decision === "BUY" ? '#22c55e' : '#ef4444' }}>{data.decision}</div>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px', marginBottom: '30px' }}>
                <div style={{ background: 'white', padding: '30px', borderRadius: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
                  <div>
                    <h3 style={{ margin: 0, fontSize: '22px' }}>{data.symbol}</h3>
                    <p style={{ color: '#64748b', marginTop: '5px' }}>Avg Price: <b>₹{holdings[data.symbol]?.avgPrice.toFixed(2) || '0.00'}</b> | Shares: <b>{holdings[data.symbol]?.qty || 0}</b></p>
                  </div>
                  <div style={{ display: 'flex', gap: '15px' }}>
                    <button onClick={() => executeTrade("BUY")} style={{ padding: '15px 35px', background: '#22c55e', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>BUY</button>
                    <button onClick={() => executeTrade("SELL")} style={{ padding: '15px 35px', background: '#ef4444', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>SELL</button>
                  </div>
                </div>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
                   <div style={{ fontSize: '12px', color: '#64748b', fontWeight: 'bold' }}>SHIELD ENGINE</div>
                   <div style={{ color: '#22c55e', fontWeight: 'bold', marginTop: '5px' }}>🛡️ ACTIVE</div>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '30px' }}>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)' }}>
                  <h3>Momentum Graph (1s Real-time)</h3>
                  <div style={{ height: '300px' }}><Line data={liveGraphData} options={{ maintainAspectRatio: false, animation: { duration: 0 } }} /></div>
                </div>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', textAlign: 'center' }}>
                  <h3>Allocation</h3>
                  <div style={{ height: '220px', display: 'flex', justifyContent: 'center' }}><Pie data={pieData} /></div>
                  <p style={{ marginTop: '15px', fontWeight: 'bold', color: '#64748b' }}>Status: {data.regime}</p>
                </div>
              </div>
            </>
          )}

          {/* 📈 UPGRADED ANALYTICS TAB with Backtesting */}
{activeTab === "Analytics" && (
  <div style={{ animation: 'fadeIn 0.5s ease-in-out' }}>
    
    {/* Top Summary Cards */}
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' }}>
      <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
        <div style={{ color: '#64748b', fontSize: '12px' }}>AI PREDICTION ACCURACY</div>
        <div style={{ fontSize: '32px', fontWeight: '900', color: '#4facfe' }}>94.2%</div>
      </div>
      <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
        <div style={{ color: '#64748b', fontSize: '12px' }}>TOTAL AUTO-TRADES</div>
        <div style={{ fontSize: '32px', fontWeight: '900', color: '#166534' }}>128</div>
      </div>
      <div style={{ background: 'white', padding: '20px', borderRadius: '20px', border: '1px solid #e2e8f0', textAlign: 'center' }}>
        <div style={{ color: '#64748b', fontSize: '12px' }}>SUCCESS RATIO</div>
        <div style={{ fontSize: '32px', fontWeight: '900', color: '#3fb950' }}>82%</div>
      </div>
    </div>

    <div style={{ background: 'white', padding: '30px', borderRadius: '24px', boxShadow: '0 4px 20px rgba(0,0,0,0.05)', marginBottom: '30px' }}>
      <h3 style={{ marginBottom: '25px' }}>📊 Portfolio Price Comparison</h3>
      <div style={{ height: '300px' }}>
        <Bar 
          data={{
            labels: ['HDFC', 'SBI', 'ICICI', 'Reliance', 'TCS', 'Infosys', 'Adani', 'ITC'],
            datasets: [{
              label: 'Price (₹)',
              data: [816.70, 1142.50, 950.00, 2450.00, 3800.00, 1420.00, 3100.00, 420.00],
              backgroundColor: ['#4facfe', '#f85149', '#d2a8ff', '#3fb950', '#f1e05a', '#00f2fe', '#64748b', '#ff7849'],
              borderRadius: 8
            }]
          }} 
          options={{ maintainAspectRatio: false }} 
        />
      </div>
    </div>

    {/* 📋 Trade History Execution Log */}
    <div style={{ background: 'white', padding: '30px', borderRadius: '24px', border: '1px solid #f1f5f9' }}>
      <h3 style={{ marginBottom: '20px' }}>📋 AI Backtesting Execution Log</h3>
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ textAlign: 'left', color: '#64748b', borderBottom: '2px solid #f1f5f9' }}>
            <th style={{ padding: '12px' }}>Timestamp</th>
            <th>Stock</th>
            <th>Signal</th>
            <th>Result</th>
            <th>Profit/Loss</th>
          </tr>
        </thead>
        <tbody style={{ fontSize: '14px' }}>
          <tr style={{ borderBottom: '1px solid #f8fafc' }}>
            <td style={{ padding: '12px' }}>15 Mar 2026, 14:20</td>
            <td><b>TCS.NS</b></td>
            <td style={{ color: '#22c55e', fontWeight: 'bold' }}>BUY</td>
            <td>AUTO-SELL (Target)</td>
            <td style={{ color: '#22c55e' }}>+ ₹19.40</td>
          </tr>
          <tr style={{ borderBottom: '1px solid #f8fafc' }}>
            <td style={{ padding: '12px' }}>15 Mar 2026, 11:45</td>
            <td><b>SBIN.NS</b></td>
            <td style={{ color: '#22c55e', fontWeight: 'bold' }}>BUY</td>
            <td>AUTO-SELL (Stop Loss)</td>
            <td style={{ color: '#ef4444' }}>- ₹5.20</td>
          </tr>
          <tr>
            <td style={{ padding: '12px' }}>14 Mar 2026, 16:10</td>
            <td><b>RELIANCE.NS</b></td>
            <td style={{ color: '#ef4444', fontWeight: 'bold' }}>AVOID</td>
            <td>REJECTED BY AI</td>
            <td>--</td>
          </tr>
        </tbody>
      </table>
    </div>

  </div>
)}

          {activeTab === "Stocks" && (
            <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
              <h3>💹 Live Asset Watchlist</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
                <thead><tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b' }}><th style={{ padding: '15px', textAlign: 'left' }}>Stock</th><th style={{ textAlign: 'left' }}>Price</th><th style={{ textAlign: 'left' }}>Action</th></tr></thead>
                <tbody>{stockList.map(s => (<tr key={s.symbol} style={{ borderBottom: '1px solid #f1f5f9' }}><td style={{ padding: '15px', fontWeight: 'bold' }}>{s.name}</td><td>₹{s.symbol === "HDFCBANK.NS" ? "816.70" : "1,142.50"}</td><td><button onClick={() => { setSelectedStock(s.symbol); setActiveTab("Dashboard"); }} style={{ background: '#4facfe', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Analyze</button></td></tr>))}</tbody>
              </table>
            </div>
          )}

          {activeTab === "Settings" && (
            <div style={{ background: 'white', padding: '40px', borderRadius: '24px' }}>
              <h3>System Preferences</h3>
              <p style={{ color: '#64748b' }}>Account: <b>Suresh Raj</b></p>
              <hr style={{ border: '0.5px solid #f1f5f9', margin: '20px 0' }} />
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div><b>Algo-Trading Mode</b><p style={{ fontSize: '12px', color: '#64748b' }}>Enable auto-execution of target/stoploss</p></div>
                <div style={{ color: '#22c55e', fontWeight: 'bold' }}>ENABLED</div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function MiniCard({ title, value, color }) {
  return (
    <div style={{ background: 'white', padding: '25px', borderRadius: '20px', border: '1px solid #f1f5f9', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
      <div style={{ color: '#64748b', fontSize: '12px', fontWeight: 'bold', marginBottom: '5px' }}>{title}</div>
      <div style={{ fontSize: '24px', fontWeight: '800' }}>{value}</div>
      <div style={{ marginTop: '10px', width: '40px', height: '4px', background: color, borderRadius: '2px' }}></div>
    </div>
  );
}

export default App;
